import{_ as a,c as n,o as e,ag as i}from"./chunks/framework.CQuhCYrb.js";const b=JSON.parse('{"title":"Running-WikiJS","description":"","frontmatter":{"title":"Running-WikiJS"},"headers":[],"relativePath":"general/running-wikijs.md","filePath":"general/running-wikijs.md","lastUpdated":null}'),p={name:"general/running-wikijs.md"};function l(r,s,t,c,o,u){return e(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="running-wikijs" tabindex="-1">Running-WikiJS <a class="header-anchor" href="#running-wikijs" aria-label="Permalink to &quot;Running-WikiJS&quot;">​</a></h1><h2 id="configure-wiki-js-with-docker-compose" tabindex="-1">Configure Wiki.js with Docker Compose <a class="header-anchor" href="#configure-wiki-js-with-docker-compose" aria-label="Permalink to &quot;Configure Wiki.js with Docker Compose&quot;">​</a></h2><p>Using Docker Compose simplifies the process of updating Wiki.js while ensuring safe practices. This is a matter of personal preference, but it&#39;s a highly recommended approach for managing Dockerized services.</p><h3 id="configure-wiki-js" tabindex="-1">Configure Wiki.js <a class="header-anchor" href="#configure-wiki-js" aria-label="Permalink to &quot;Configure Wiki.js&quot;">​</a></h3><p>Create the following <code>docker-compose.yml</code> file in a user home directory for Wiki.js. Refer to the <a href="/server-guides/linux-server-initial-setup.html">Server Initial Setup</a> guide for preliminary server setup.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>version: &quot;3&quot;</span></span>
<span class="line"><span>services:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  db:</span></span>
<span class="line"><span>    image: postgres:15-alpine</span></span>
<span class="line"><span>    environment:</span></span>
<span class="line"><span>      POSTGRES_DB: wiki</span></span>
<span class="line"><span>      POSTGRES_PASSWORD: super_secret_here</span></span>
<span class="line"><span>      POSTGRES_USER: wikijs</span></span>
<span class="line"><span>    logging:</span></span>
<span class="line"><span>      driver: &quot;none&quot;</span></span>
<span class="line"><span>    restart: unless-stopped</span></span>
<span class="line"><span>    volumes:</span></span>
<span class="line"><span>      - db-data:/var/lib/postgresql/data</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  wiki:</span></span>
<span class="line"><span>    image: ghcr.io/requarks/wiki:2</span></span>
<span class="line"><span>    depends_on:</span></span>
<span class="line"><span>      - db</span></span>
<span class="line"><span>    environment:</span></span>
<span class="line"><span>      DB_TYPE: postgres</span></span>
<span class="line"><span>      DB_HOST: db</span></span>
<span class="line"><span>      DB_PORT: 5432</span></span>
<span class="line"><span>      DB_USER: wikijs</span></span>
<span class="line"><span>      DB_PASS: super_secret_here</span></span>
<span class="line"><span>      DB_NAME: wiki</span></span>
<span class="line"><span>    restart: unless-stopped</span></span>
<span class="line"><span>    ports:</span></span>
<span class="line"><span>      - &quot;XZY:3000&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>volumes:</span></span>
<span class="line"><span>  db-data:</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br></div></div><ul><li><p>Update the port where it says <code>XZY</code> (e.g., <code>80:3000</code> for typical use). If using [adjust to your desired port.</p></li><li><p>Replace the placeholder passwords (<code>super_secret_here</code>) with secure values.</p></li></ul><h3 id="run-wiki-js" tabindex="-1">Run Wiki.js <a class="header-anchor" href="#run-wiki-js" aria-label="Permalink to &quot;Run Wiki.js&quot;">​</a></h3><p>To run Wiki.js, execute the following command:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>docker compose up -d</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="update-wiki-js" tabindex="-1">Update Wiki.js <a class="header-anchor" href="#update-wiki-js" aria-label="Permalink to &quot;Update Wiki.js&quot;">​</a></h3><p>To safely update Wiki.js, use:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>docker-compose pull &amp;&amp; docker-compose up -d</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>This command will pull the latest images specified in your <code>docker-compose.yml</code> file and restart the containers in detached mode.</p><h3 id="backup-wiki-js" tabindex="-1">Backup Wiki.js <a class="header-anchor" href="#backup-wiki-js" aria-label="Permalink to &quot;Backup Wiki.js&quot;">​</a></h3><p>Backup your data before updating or making significant changes. Use the following command to create a database dump:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>docker exec -t db pg_dumpall -c -U wikijs &gt; dump_$(date +&quot;%d-%m-%Y_%H-%M-%S&quot;).sql</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li>Replace <code>db</code> with the name of your database container if it&#39;s different.</li></ul><p>Verify the logs of your Wiki.js container after the update to ensure it’s running correctly:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>docker logs wiki</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>To restore the backup if needed:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>cat your_backup.sql | docker exec -i db psql -U wikijs</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li>Replace <code>your_backup.sql</code> with the actual path to your backup file.</li></ul><h3 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h3><ul><li><p>Always test updates in a non-production environment to avoid disruption to live users.</p></li><li><p>Ensure the backup is valid and retrievable before making changes.</p></li><li><p>Monitor the logs for any errors post-update to take corrective actions quickly.</p></li></ul><p>,</p>`,26)])])}const m=a(p,[["render",l]]);export{b as __pageData,m as default};
